import { MakeLogicType, actions, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { GoogleAdsConversionActionType } from '~/types'

export interface GoogleAdsAccount {
    id: string
    level: string
    name: string
    parent_id: string
    manager?: boolean
    test_account?: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface googleAdsIntegrationLogicValues {
    googleAdsAccessibleAccounts: GoogleAdsAccount[] | null
    googleAdsAccessibleAccountsLoading: boolean
    googleAdsAccessibleAccountsError: string | null
    googleAdsConversionActions: GoogleAdsConversionActionType[] | null
    googleAdsConversionActionsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface googleAdsIntegrationLogicActions {
    loadGoogleAdsAccessibleAccounts: () => {
        value: true
    }
    loadGoogleAdsAccessibleAccountsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadGoogleAdsAccessibleAccountsSuccess: (
        googleAdsAccessibleAccounts: GoogleAdsAccount[],
        payload?: {
            value: true
        }
    ) => {
        googleAdsAccessibleAccounts: GoogleAdsAccount[]
        payload?: {
            value: true
        }
    }
    loadGoogleAdsConversionActions: (
        customerId: string,
        parentId: string
    ) => {
        customerId: string
        parentId: string
    }
    loadGoogleAdsConversionActionsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadGoogleAdsConversionActionsSuccess: (
        googleAdsConversionActions: GoogleAdsConversionActionType[],
        payload?: {
            customerId: string
            parentId: string
        }
    ) => {
        googleAdsConversionActions: GoogleAdsConversionActionType[]
        payload?: {
            customerId: string
            parentId: string
        }
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface googleAdsIntegrationLogicProps {
    id: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface googleAdsIntegrationLogicMeta {
    key: number
}

export type googleAdsIntegrationLogicType = MakeLogicType<
    googleAdsIntegrationLogicValues,
    googleAdsIntegrationLogicActions,
    googleAdsIntegrationLogicProps,
    googleAdsIntegrationLogicMeta
>

export const googleAdsIntegrationLogic = kea<googleAdsIntegrationLogicType>([
    props({} as { id: number }),
    key((props) => props.id),
    path((key) => ['lib', 'integrations', 'googleAdsIntegrationLogic', key]),
    actions({
        loadGoogleAdsConversionActions: (customerId: string, parentId: string) => ({ customerId, parentId }),
        loadGoogleAdsAccessibleAccounts: true,
    }),
    loaders(({ props }) => ({
        googleAdsConversionActions: [
            null as GoogleAdsConversionActionType[] | null,
            {
                loadGoogleAdsConversionActions: async ({
                    customerId,
                    parentId,
                }: {
                    customerId: string
                    parentId: string
                }) => {
                    const res = await api.integrations.googleAdsConversionActions(props.id, {
                        customerId,
                        parentId,
                    })
                    return res.conversionActions
                },
            },
        ],
        googleAdsAccessibleAccounts: [
            null as GoogleAdsAccount[] | null,
            {
                loadGoogleAdsAccessibleAccounts: async () => {
                    const res = await api.integrations.googleAdsAccounts(props.id)
                    return res.accessibleAccounts
                },
            },
        ],
    })),
    reducers({
        googleAdsAccessibleAccountsError: [
            null as string | null,
            {
                loadGoogleAdsAccessibleAccounts: () => null,
                loadGoogleAdsAccessibleAccountsSuccess: () => null,
                loadGoogleAdsAccessibleAccountsFailure: (_, { error, errorObject }) =>
                    errorObject?.detail ?? error ?? 'Could not load your Google Ads accounts.',
            },
        ],
    }),
])
